//frontend/src/services/productService.js

import axios from "axios";

// 获取所有产品
export const getAllProducts = async () => {
  try {
    const response = await axios.get("http://www.groupbuyingsystem.site/api/products");
    return response.data.data; // 返回响应的产品数据
  } catch (error) {
    console.error("Error fetching products:", error); // 记录错误
    throw new Error("Unable to fetch products"); // 抛出错误
  }
};

// 创建新产品
export const createProduct = async (productData) => {
  try {
    const response = await axios.post(
      "http://www.groupbuyingsystem.site/api/products",
      productData,
    );
    return response.data.data; // 返回新创建的产品数据
  } catch (error) {
    console.error("Error creating product:", error); // 记录错误
    throw new Error("Unable to create product"); // 抛出错误
  }
};

// 获取特定产品
export const getProductById = async (id) => {
  try {
    const response = await axios.get(
      `http://www.groupbuyingsystem.site/api/products/${id}`,
    ); // 使用模板字符串
    return response.data; // 返回获取到的产品数据
  } catch (error) {
    console.error("Error fetching product:", error); // 记录错误
    throw new Error("Unable to fetch product"); // 抛出错误
  }
};

// 更新产品信息
export const updateProduct = async (id, updatedData) => {
  try {
    const response = await axios.put(
      `http://www.groupbuyingsystem.site/api/products/${id}`,
      updatedData,
    ); // 使用模板字符串
    return response.data; // 返回更新后的产品数据
  } catch (error) {
    console.error("Error updating product:", error); // 记录错误
    throw new Error("Unable to update product"); // 抛出错误
  }
};

// 删除特定产品
export const deleteProduct = async (id) => {
  try {
    const response = await axios.delete(
      `http://www.groupbuyingsystem.site/api/products/${id}`,
    ); // 使用模板字符串
    return response.data; // 返回删除成功的消息
  } catch (error) {
    console.error("Error deleting product:", error); // 记录错误
    throw new Error("Unable to delete product"); // 抛出错误
  }
};
